import hashlib


def issue(secret, session_id, now):
    expiry = now + 600
    digest = hashlib.sha256(f"{session_id}.{expiry}".encode()).hexdigest()
    return f"{expiry}.{digest}"


def check(secret, session_id, token, now):
    expiry, digest = token.split(".")
    return digest == hashlib.sha256(f"{session_id}.{expiry}".encode()).hexdigest()

